// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 initialBalance, uint64 blockNum) public {
        initialBalance = bound(initialBalance, 10 ether, type(uint64).max);
        blockNum = uint64(bound(blockNum, 0, type(uint64).max - 1));
        vm.assume(blockNum > 0);
        vm.assume(blockNum % 15 == 0);

        address sender = makeAddr("sender");
        vm.deal(sender, initialBalance);
        vm.roll(blockNum);
        vm.warp(1);

        vm.prank(sender);
        (bool success, ) = address(c).call{value: 10 ether}("");
        require(success, "Fallback failed");

        assertEq(address(c).balance, 0, "Balance should be 0 after payout block");
    }
}
